mapper.select:
SELECT count(*) FROM org02_info
 WHERE org02_code_id = #{codeId} AND org02_mod_date = #{modDate}
   AND org02_info_id != #{infoId}

mapper.update:
UPDATE org01_code
   SET org01_close_date   = #{req.closeDate},
       org01_close_reason = #{req.closeReason}
 WHERE org01_code_id = #{req.codeId}
   AND org01_company_id = #{companyId}

mapper.delete:
DELETE FROM org02_info
 WHERE org02_info_id = #{infoId}
   AND org02_code_id IN (SELECT org01_code_id FROM org01_code WHERE org01_company_id = #{companyId})
